We consider the
following initial boundary value problem for the wave equation with a potential $q$ and an absorption coefficient $a$,
\begin{equation}\label{1.1}
\left\{
\begin{array}{llll}
\para{\partial^2_t-\Delta+a(x)\partial_t+q(x)}u=0  & \textrm{in }\; Q,\cr
u(\cdot,0 )=\partial_tu(\cdot,0)=0 & \textrm{in }\; \mathrm{M} ,\cr
u=f & \textrm{on } \; \Sigma.
\end{array}
\right.
\end{equation}

In local coordinates, we have
\begin{equation}\label{1.2}
\nabla f=\sum_{i,j=1}^n\mathrm{g}^{ij}\frac{\partial f}{\partial x^i}\frac{\partial}{\partial x^j} ,
\end{equation}
where $(\mathrm{g}^{i,j})$ is the inverse of the tensor $\mathrm{g}$.

\label{L.1.1}
Let $T>0$, $a\in L^\infty(\mathrm{M})$, and $q\in L^\infty(\mathrm{M})$. Assuming $F\in H^1(0,T;L^2(\mathrm{M}))$ such that $F(\cdot,0)=0$ in $\mathrm{M}$, then there exists a unique solution
$v$ to \eqref{1.4} such that
 $$
 v\in \mathcal{C}^2(0,T;L^2(\mathrm{M}))\cap \mathcal{C}^1(0,T;H^1_0(\mathrm{M}))\cap \mathcal{C}(0,T; H^2(\mathrm{M})).
 $$ 
 Furthermore, there is a constant $C>0$ such that
\begin{equation}\label{1.5}
\norm{\partial_tv(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla v(\cdot,t)}_{L^2(\mathrm{M})}\leq
C\norm{F}_{L^2(Q)},
\end{equation}
and
\begin{equation}\label{1.6}
\norm{\partial_t^2 v(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\nabla\partial_t v(\cdot,t)}_{L^2(\mathrm{M})}+\norm{\Delta v(\cdot,t)}_{L^2(\mathrm{M})}\leq C\norm{F}_{H^1(0,T;L^2(\mathrm{M}))}.
\end{equation}

\label{L.1.2}
Let $f\in H^1(\Sigma)$ be a function such that $f(x,0)=0$ for all $x\in\partial\mathrm{M}$.
There exists an unique solution
\begin{equation}\label{1.7}
u\in \mathcal{C}^1(0,T;L^2(\mathrm{M}))\cap \mathcal{C}(0,T;H^1(\mathrm{M}))
\end{equation}
to the problem (\ref{1.1}).  Furthermore, there is a
constant $C>0$ such that
\begin{equation}\label{1.8}
\norm{\partial_\nu u}_{L^2(\Sigma)}\leq C\norm{f}_{H^1(\Sigma)}.
\end{equation}

\label{Th2}
Let $(\mathrm{M},\mathrm{g})$ be a simple compact Riemannian manifold with boundary of dimension $n \geq 2$ such that $k^+(\mathrm{M},\mathrm{g})<1$, and let $T>\textrm{Diam}_\mathrm{g}(\mathrm{M})$.
There exist  $C>0$ and $\gamma\in(0,1)$ such that for any $a_1,a_2\in\mathscr{A}(m_1,\eta)$ and $q_1,q_2\in\mathscr{Q}(m_2)$ coincide near the boundary $\partial\mathrm{M}$, the following estimate holds true
\begin{equation}\label{1.12}
\norm{a_1-a_2}_{L^2(\mathrm{M})}+\norm{q_1-q_2}_{L^2(\mathrm{M})}\leq C\norm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}^\gamma
\end{equation}
where $C$ depends on $\mathrm{M}$, $m_1,m_2$, $\eta$ and $n$.

By
\begin{align*}
S\mathrm{M}=\set{(x,\xi)\in T\mathrm{M};\,\abs{\xi}=1}, \quad
S^*\mathrm{M}=\set{(x,p)\in T^*\mathrm{M};\,\abs{p}=1},
\end{align*}
we denote the sphere bundle and co-sphere bundle of $\mathrm{M}$.

The exponential map $\exp_x:T_x\mathrm{M}\to \mathrm{M}$ is given by
\begin{equation}\label{2.1}
\exp_x(v)=\gamma_{x,\xi}(\abs{v}),\quad \xi=\frac{v\,\,}{\abs{v}}.
\end{equation}

We define the geodesic flow $\phi_t$ as following
\begin{equation}\label{2.2}
\phi_t:S\mathrm{M}\to S\mathrm{M},\quad \phi_t(x,\xi)=(\gamma_{x,\xi}(t),\dot{\gamma}_{x,\xi}(t)),\quad t\in [\ell_-(x,\xi),\ell_+(x,\xi)],
\end{equation}
and $\phi_t$ is a flow, that is, $\phi_t\circ\phi_s=\phi_{t+s}$.

Now, we introduce the submanifolds of inner and outer vectors of $S\mathrm{M}$
\begin{equation}\label{2.3}
\partial_{\pm}S\mathrm{M} =\set{(x,\xi)\in S\mathrm{M},\, x \in \partial \mathrm{M},\, \pm\seq{\xi,\nu(x)}< 0},
\end{equation}
where $\nu$ is the unit outer normal to the boundary.

The ray transform (also called geodesic $X$-ray transform) on a convex non trapping manifold $\mathrm{M}$ is the linear operator
\begin{equation}\label{2.5}
\mathcal{I}:\mathcal{C}^\infty(\mathrm{M})\longrightarrow \mathcal{C}^\infty(\partial_+S\mathrm{M}),
\end{equation}
defined by the equality
\begin{equation}\label{2.6}
\mathcal{I} f(x,\xi)=\int_0^{\ell_+(x,\xi)}f(\gamma_{x,\xi}(t))\, \mathrm{d} t,\quad (x,\xi)\in\partial_+S\mathrm{M}.
\end{equation}

The ray transform on a convex non trapping manifold $\mathrm{M}$ can be extended as a bounded operator
\begin{equation}\label{2.7}
\mathcal{I}:H^k(\mathrm{M})\longrightarrow H^k(\partial_+S\mathrm{M}),
\end{equation}
for every integer $k\geq 1$, see Theorem 4.2.1 of \cite{[Sh]}.

It is called the sectional curvature of the manifold $\mathrm{M}$ at the point $x$ and in the two-dimentional direction $\pi$.\\
For $(x,\xi)\in T\mathrm{M}$, we set $K(x,\xi)=\underset{\pi \ni \xi}{\sup} K(x,\pi) $ and
\begin{equation}\label{2.8}
 K^+(x,\xi)=\max\{0,K(x,\xi)\}. 
\end{equation}

For a simple compact Riemannian manifold $(\mathrm{M},\mathrm{g})$, we set 
 \begin{equation}\label{2.9}
 k^+(\mathrm{M},\mathrm{g})=\sup\lbrace \int_0^{\ell_+(x,\xi)} tK^+(\gamma_{x,\xi}(t),\dot{\gamma}_{x,\xi}(t)) dt, \; (x,\xi)\in \partial_+S\mathrm{M}\rbrace.
 \end{equation}

\label{theorem}
For every simple compact Riemannian manifold $(\mathrm{M},\mathrm{g})$ with $k^+(\mathrm{M},\mathrm{g})<1$, there exist $C>0$ such that the following stability estimate 
\begin{equation}\label{2.10}
 \Vert f \Vert _{L^2(\mathrm{M})}\leq C \Vert \mathcal{I} f \Vert_{H^1(\partial_+S\mathrm{M})}, 
\end{equation} 
holds for any $f\in H^1(\mathrm{M})$.

The notation $\mathcal{C}^{\infty}(\tau_s^r\mathrm{M},\mathrm{M})$ will usually be abbreviated to $\mathcal{C}^{\infty}(\tau_s^r\mathrm{M}).$
  If $(x^1,\dots,x^n)$ is a local coordinate system defined in a domain $U$, then any tensor field $u\in \mathcal{C}^{\infty}(\tau_s^r \mathrm{M},U)$ can be uniquely represented as
\begin{equation}\label{2.11}
u=u_{j_1,\dots,j_s}^{i_1,\dots,i_r} \frac{\partial}{\partial x^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial x^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s},
\end{equation}
where $u_{j_1,\cdots,j_s}^{i_1,\cdots,i_r} \in \mathcal{C}^{\infty}(U)$ are called the coordinates of the field $u$ in the given coordinate system.

\begin{equation}\label{2.15}
\nabla_ku_{j_1\dots j_s}^{i_1\dots i_r} =\frac{\partial}{\partial x^k}u_{j_1\dots j_s}^{i_1 \dots i_r}+\sum_{m=1}^r\Gamma^{i_m}_{kp}u_{j_1 \dots j_s}^{i_1 \dots i_{m-1} p i_{m+1} \dots i_r}-\sum_{m=1}^s\Gamma^{p}_{kj_m}u_{j_1 \dots j_{m-1} p j_{m+1} \dots j_s}^{i_1 \dots  i_r},
\end{equation}

The algebra of tensor fields of the manifold $T\mathrm{M}$ is generated locally by the coordinate fields $\frac{\partial}{\partial x^i},\frac{\partial}{\partial \xi^i}, dx^i, d\xi^i.$ A tensor $u \in T^r_{s,(x,\xi)}(T\mathrm{M})$ of degree $(r,s)$ at a point $(x,\xi)\in T\mathrm{M}$ is called \textit{semibasic} if in some (and so, in any) natural coordinate system, it can be represented as:
\begin{equation}\label{2.16}
u=u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}.
\end{equation}

\begin{equation}\label{2.18}
\overset{\mathrm{v}}{\nabla}u =\overset{\mathrm{v}}{\nabla}_k u_{j_1 \dots j_s}^{i_1 \dots i_r} \frac{\partial}{\partial \xi^{i_1}}\otimes\dots\otimes\frac{\partial}{\partial \xi^{i_r}}\otimes dx^{j_1} \otimes \dots \otimes dx^{j_s}\otimes dx^k,
